44	
45	  describe("quote — policy-wide modifiers", () => {
46	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
47	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
48	    it.todo("a first insurance carries a 10 % initial assessment surcharge on the policy base premium");
49	    it.todo("each contract after the customer's first gets a 15 % discount");
50	    it.todo("a 5 G processing fee is added to every premium");
51	  });
52	
53	  describe("quote — rounding in the MHPCO's favor", () => {
54	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
55	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
56	  });
57	
58	  describe("quote — integration examples", () => {
59	    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
60	    it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
61	  });
62	
63	  describe("quote — errors", () => {
64	    it.todo("an item with an unknown type (e.g. broomstick) → error");
65	  });
66	
67	  describe("claim — standard reimbursement", () => {
68	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
